        raise ValueError("Incompatible matrix dimensions")
    return [[a[i][j] + scale_b * b[i][j] for j in range(len(a[0]))]
            for i in range(len(a))]


def outer(a: list[Q], b: list[Q]) -> Matrix:
    return [[x * y for y in b] for x in a]


